using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Mvc;using TransPort.Api.Controllers;using TransPort.Api.Modules.Gps.DTOs;using TransPort.Api.Modules.Gps.Repositories;
namespace TransPort.Api.Tests;
public sealed class GpsControllerTests
{
 [Fact]public async Task Resumen_PropagaAlcance(){var r=new F();await C(r,12,"Empleado").Resumen(default);Assert.Equal(new AlcanceGps(12,false),r.Alcance);}
 [Fact]public async Task Simular_TextoValido_DevuelveId(){var r=new F{Id=31};var x=Assert.IsType<OkObjectResult>(await C(r,1,"AdministradorGeneral").Simular(new(){DispositivoId=2,DatosFuente="{\"latitud\":14.634915,\"longitud\":-90.506882,\"velocidad\":35.5}"},default));Assert.Equal(31,Assert.IsType<ResultadoGpsDto>(x.Value).Id);Assert.Equal(14.634915m,r.Evento?.Latitud);}
 [Fact]public async Task Simular_TextoInvalido_DevuelveBadRequest()=>Assert.IsType<BadRequestObjectResult>(await C(new F(),1,"AdministradorGeneral").Simular(new(){DispositivoId=1,DatosFuente="no-json"},default));
 [Fact]public async Task Atender_PropagaAlcance(){var r=new F();Assert.IsType<NoContentResult>(await C(r,4,"Operativo").Atender(1,default));Assert.Equal(new AlcanceGps(4,false),r.Alcance);}
 [Fact]public void Controlador_ExcluyeCliente(){var a=typeof(GpsController).GetCustomAttributes(typeof(AuthorizeAttribute),true).Cast<AuthorizeAttribute>().Single();Assert.DoesNotContain("Cliente",a.Roles??"");}
 private static GpsController C(IGpsRepository r,int id,params string[]roles){var cs=new List<Claim>{new(ClaimTypes.NameIdentifier,id.ToString())};cs.AddRange(roles.Select(x=>new Claim(ClaimTypes.Role,x)));return new(r){ControllerContext=new(){HttpContext=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity(cs,"T"))}}};}
 private sealed class F:IGpsRepository{public long Id{get;init;}public AlcanceGps?Alcance{get;private set;}public GpsEventoFuenteDto?Evento{get;private set;}public Task<GpsResumenDto>ResumenAsync(AlcanceGps a,CancellationToken ct){Alcance=a;return Task.FromResult(new GpsResumenDto([],[]));}public Task<IReadOnlyList<GpsPosicionDto>>RecorridoAsync(int id,DateTime?d,DateTime?h,AlcanceGps a,CancellationToken ct)=>Task.FromResult<IReadOnlyList<GpsPosicionDto>>([]);public Task<GpsOpcionesDto>OpcionesAsync(AlcanceGps a,CancellationToken ct)=>Task.FromResult(new GpsOpcionesDto([],[]));public Task<int>CrearAsync(CrearGpsDispositivoRequest x,AlcanceGps a,CancellationToken ct)=>Task.FromResult((int)Id);public Task<long>SimularAsync(int id,GpsEventoFuenteDto e,string raw,AlcanceGps a,CancellationToken ct){Alcance=a;Evento=e;return Task.FromResult(Id);}public Task<bool>AtenderAsync(long id,AlcanceGps a,CancellationToken ct){Alcance=a;return Task.FromResult(true);}public Task<bool>EliminarAsync(int id,int u,CancellationToken ct)=>Task.FromResult(true);}
}
